.cta {
  text-align: center;
  padding: 2rem 0 3rem;

  [tuiButton] {
    background: linear-gradient(135deg, gt.$accent-orange, gt.$accent-orange-light);
    border: none;
    color: #fff;
    font-size: 1.125rem;
    padding: 0.75rem 2rem;

    &:hover {
      background: linear-gradient(135deg, gt.$accent-orange-light, gt.$accent-orange);
    }
  }
}

